<script setup>
import { assetUrl } from '../assets.js';
import { computed, ref, watch } from 'vue';
import { Search, ArrowUpRight, ArrowRight, ArrowLeft, Bookmark, Clock3, X, WandSparkles } from '@lucide/vue';
import { articles, categories, findArticles } from '../knowledge.js';
const props=defineProps({search:String,favorites:Array});
const emit=defineEmits(['update:search','open','favorite','navigate']);
const category=ref('全部'),activeId=ref('earth');
const results=computed(()=>findArticles(articles,category.value,props.search));
const featured=computed(()=>results.value.find(a=>a.id===activeId.value)||results.value[0]||articles[2]);
const index=computed(()=>results.value.findIndex(a=>a.id===featured.value.id));
function step(direction){if(!results.value.length)return;activeId.value=results.value[(index.value+direction+results.value.length)%results.value.length].id}
function scrollLibrary(){document.getElementById('explore-library')?.scrollIntoView({behavior:'smooth'})}
</script>
<template>
 <div class="explore-v2"><section class="explore-hero"><div class="explore-atmosphere"></div><div class="explore-hero-inner"><div class="explore-copy"><button class="explore-studio-entry" @click="emit('navigate','studio')"><WandSparkles :size="17"/> 制作知识卡 <ArrowUpRight :size="15"/></button><span class="light-eyebrow">一个更容易理解的宇宙</span><h1>探索宇宙，<br/>发现世界的另一面。</h1><p>从一颗行星，到一束跨越百万年的星光。<br/>用真实影像与通俗故事，回答你抬头时的疑问。</p><div class="explore-actions"><button class="button primary" @click="scrollLibrary">浏览科普故事 <ArrowRight :size="17"/></button><button class="button secondary" @click="emit('open',featured)">了解{{featured.keywords[0]}} <ArrowUpRight :size="17"/></button></div><div class="explore-current"><span class="current-rule"></span><span>{{featured.category}} / {{featured.tag}}<strong>{{featured.title}}</strong></span><div class="explore-arrows"><button class="icon-button" aria-label="上一个精选天体" :disabled="results.length<2" @click="step(-1)"><ArrowLeft :size="17"/></button><button class="icon-button" aria-label="下一个精选天体" :disabled="results.length<2" @click="step(1)"><ArrowRight :size="17"/></button></div></div></div><div class="explore-visual"><span class="visual-orbit orbit-a"></span><span class="visual-orbit orbit-b"></span><Transition name="planet-swap" mode="out-in"><button :key="featured.id" class="explore-planet" :class="{'earth-round':featured.image==='earth','moon-round':featured.image==='moon'}" :aria-label="'阅读'+featured.title" @click="emit('open',featured)"><img :src="assetUrl('/images/'+featured.image+'.jpg')" :alt="featured.title"/><span class="visual-image-hint">点击影像，打开故事 <ArrowUpRight :size="15"/></span></button></Transition><span class="image-marker">REAL IMAGES.<br/>REAL CURIOSITY.</span><span class="explore-image-note">{{featured.image==='blackhole'?'NASA 艺术概念图':'NASA 天文影像'}} · 署名见详情</span></div></div><div class="explore-topic-nav"><button v-for="(c,i) in categories" :class="{selected:category===c}" :aria-pressed="category===c" @click="category=c;emit('update:search','')"><span>0{{i+1}}</span>{{c==='全部'?'全部宇宙':c}}<ArrowUpRight :size="13"/></button></div></section>
 <section id="explore-library" class="page-shell"><div class="section-top"><div><span class="light-eyebrow">每一个故事，都有真实的来源</span><h2>宇宙知识库</h2></div><span class="library-number">{{results.length}} 篇科普故事</span></div><div class="search-field"><Search :size="19"/><input aria-label="搜索天文知识" :value="search" @input="emit('update:search',$event.target.value)" placeholder="搜索一个天体，或一个让你好奇的问题…"/><button v-if="search" class="icon-button" aria-label="清除搜索" @click="emit('update:search','')"><X :size="17"/></button></div><div class="filter-row" aria-label="知识分类"><button v-for="c in categories" :class="{selected:category===c}" :aria-pressed="category===c" @click="category=c">{{c}}</button></div><TransitionGroup v-if="results.length" name="cards" tag="div" class="article-grid library-grid"><article v-for="a in results" :key="a.id" class="article-card"><button class="article-cover" @click="emit('open',a)"><img :src="assetUrl('/images/'+a.image+'.jpg')" :alt="a.title" loading="lazy"/><span class="cover-badge">{{a.tag}}</span><span class="cover-arrow"><ArrowUpRight :size="22"/></span></button><div class="article-info"><div class="card-meta"><span>{{a.category}}</span><span><Clock3 :size="12"/> {{a.minutes}} 分钟阅读</span></div><h3><button @click="emit('open',a)">{{a.title}}</button></h3><p>{{a.short}}</p><div class="card-bottom"><small>来源 · {{a.sourceName}}</small><button class="icon-button" :class="{favorited:favorites.includes(a.id)}" :aria-label="(favorites.includes(a.id)?'取消收藏':'收藏')+a.title" :aria-pressed="favorites.includes(a.id)" @click="emit('favorite',a)"><Bookmark :size="17"/></button></div></div></article></TransitionGroup><div v-else class="empty-state"><Search :size="32"/><h2>还没找到这颗星</h2><p>换一个关键词，或者试试其他分类。</p><button class="button secondary" @click="category='全部';emit('update:search','')">重置筛选</button></div></section></div>
</template>
